#include <bits/stdc++.h>
using namespace std;

struct Node {
    char type; // '0', '1', '?', '&', '|'
    Node *left, *right;
    Node(char t) : type(t), left(nullptr), right(nullptr) {}
};

int idx;
string s;

Node* parse_or();
Node* parse_and();
Node* parse_term();

Node* parse_term() {
    if (s[idx] == '(') {
        idx++; // '('
        Node* expr = parse_or();
        idx++; // ')'
        return expr;
    } else {
        return new Node(s[idx++]);
    }
}

Node* parse_and() {
    Node* left = parse_term();
    while (idx < (int)s.size() && s[idx] == '&') {
        idx++; // '&'
        Node* right = parse_term();
        Node* op = new Node('&');
        op->left = left;
        op->right = right;
        left = op;
    }
    return left;
}

Node* parse_or() {
    Node* left = parse_and();
    while (idx < (int)s.size() && s[idx] == '|') {
        idx++; // '|'
        Node* right = parse_and();
        Node* op = new Node('|');
        op->left = left;
        op->right = right;
        left = op;
    }
    return left;
}

struct Info {
    int cost0, cost1;
};

Info solve(Node* node) {
    if (node->type == '0') {
        return {0, 1<<30};
    } else if (node->type == '1') {
        return {1<<30, 0};
    } else if (node->type == '?') {
        return {0, 0};
    } else if (node->type == '&') {
        auto L = solve(node->left);
        auto R = solve(node->right);
        int cost0 = min({
            L.cost0 + R.cost0,
            L.cost0 + R.cost1,
            L.cost1 + R.cost0
        });
        int cost1 = L.cost1 + R.cost1;
        return {cost0, cost1};
    } else { // '|'
        auto L = solve(node->left);
        auto R = solve(node->right);
        int cost0 = L.cost0 + R.cost0;
        int cost1 = min({
            L.cost0 + R.cost1,
            L.cost1 + R.cost0,
            L.cost1 + R.cost1
        });
        return {cost0, cost1};
    }
}

