    Node r;
    // To make a&b = 0: either side 0
    r.c0 = min(a.c0 + min(b.c0, b.c1), min(a.c0, a.c1) + b.c0);
    // To make a&b = 1: both 1
    r.c1 = a.c1 + b.c1;
    return r;
