Node merge_or(const Node& a, const Node& b) {
    Node r;
    // To make a|b = 0: both 0
    r.c0 = a.c0 + b.c0;
    // To make a|b = 1: either side 1
    r.c1 = min(a.c1 + min(b.c0, b.c1), min(a.c0, a.c1) + b.c1);
    return r;
}

