#include <stdlib.h>

#define MAXN 200005

typedef struct {
    int cost0, cost1;
} Node;

char s[MAXN];
int pos, len;

Node parse_or();
Node parse_and();
Node parse_term();

Node merge_or(Node left, Node right) {
    Node res;
    // To get 0 from OR: both sides must be 0
    res.cost0 = left.cost0 + right.cost0;
    // To get 1 from OR: at least one side is 1, choose min cost
    int c1 = left.cost1 + right.cost0;
    int c2 = left.cost0 + right.cost1;
    int c3 = left.cost1 + right.cost1;
    res.cost1 = c1 < c2 ? c1 : c2;
    if (c3 < res.cost1) res.cost1 = c3;
    return res;
}

Node merge_and(Node left, Node right) {
    Node res;
    // To get 0 from AND: at least one side is 0
    int c0 = left.cost0 + right.cost0;
    int c1 = left.cost0 + right.cost1;
    int c2 = left.cost1 + right.cost0;
    res.cost0 = c0 < c1 ? c0 : c1;
    if (c2 < res.cost0) res.cost0 = c2;
    // To get 1 from AND: both sides must be 1
    res.cost1 = left.cost1 + right.cost1;
    return res;
}

Node parse_or() {
    Node left = parse_and();
    while (pos < len && s[pos] == '|') {
        pos++;
        Node right = parse_and();
        left = merge_or(left, right);
    }
    return left;
}

Node parse_and() {
    Node left = parse_term();
    while (pos < len && s[pos] == '&') {
        pos++;
        Node right = parse_term();
        left = merge_and(left, right);
    }
    return left;
}

Node parse_term() {
    if (s[pos] == '(') {
        pos++;
        Node inner = parse_or();
        pos++; // skip ')'
        return inner;
    }
    // It's '?'
    pos++;
    Node res;
    // If we pay 0, we can choose the value freely later.
    // But here: cost to force 0 is 0 if we set ? to 0, but we may need to pay if both choices give different results.
    // Actually: no payment for ? itself, payment occurs when both values are possible.
    // For a single ?, setting to 0 costs 0 for result 0, and we can’t get 1 without paying? 
    // Wait: If it's a single ?, both 0 and 1 are possible outcomes without paying.
    // But to *force* result 0, we set it to 0 (cost 0). To force 1, set to 1 (cost 0).
    // The payment logic: we pay only if both choices give different results *in the whole expression*.
    // For a single variable, 0 and 1 are different, so we *would* have to pay if we need to fix it? No, the problem says:
    // He pays when changing ? to 0 or 1 changes the evaluation result.  
    // For a standalone ?, changing 0->1 changes result, so he pays 1 to set it.
    // So cost to force 0 = 1 (pay to set to 0), cost to force 1 = 1.
    // But if it's inside context where result is forced, payment may be 0.
    // Correct: for a lone ?, both costs are 1.
    res.cost0 = 1;
    res.cost1 = 1;
    return res;
}

int main() {
    fgets(s, MAXN, stdin);
    len = strlen(s);
    if (s[len-1] == '\n') s[--len] = '\0';
    pos = 0;
    Node root = parse_or();
    printf("%d %d\n", root.cost0, root.cost1);
    return 0;
}

