} Node;

char s[MAXN];
int pos;

static inline int min2(int a, int b) { return a < b ? a : b; }

Node parse_or();

Node parse_term() {
    Node res;
    if (s[pos] == '?') {
        // Need to pay 1 to decide it as 0 or 1
        res.c0 = 1;
        res.c1 = 1;
        pos++;
    } else { // '('
        pos++; // skip '('
        res = parse_or();
        pos++; // skip ')'
    }
    return res;
}

Node parse_and() {
    Node left = parse_term();
    while (s[pos] == '&') {
        pos++;
        Node right = parse_term();
        Node res;
        // To make AND = 1, both must be 1
        res.c1 = left.c1 + right.c1;
        // To make AND = 0, at least one must be 0
        res.c0 = min2(left.c0 + min2(right.c0, right.c1),
                      right.c0 + min2(left.c0, left.c1));
        left = res;
    }
    return left;
}

Node parse_or() {
    Node left = parse_and();
    while (s[pos] == '|') {
        pos++;
        Node right = parse_and();
        Node res;
        // To make OR = 0, both must be 0
        res.c0 = left.c0 + right.c0;
        // To make OR = 1, at least one must be 1
        res.c1 = min2(left.c1 + min2(right.c0, right.c1),
                      right.c1 + min2(left.c0, left.c1));
        left = res;
    }
    return left;
}

int main() {
    if (scanf("%s", s) != 1) return 0;
    pos = 0;
    Node ans = parse_or();
    printf("%d %d\n", ans.c0, ans.c1);
