import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();

        // Stack holds int[2] where [0] = min cost for 0, [1] = min cost for 1
        Deque<int[]> stack = new ArrayDeque<>();
        Deque<Character> ops = new ArrayDeque<>();

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '?') {
                stack.push(new int[]{0, 0}); // cost 0 for both, but to force opposite we pay 1
            } else if (c == '(') {
                ops.push('(');
            } else if (c == ')') {
                // pop until '('
                while (ops.peek() != '(') {
                    applyOp(stack, ops.pop());
                }
                ops.pop(); // remove '('
            } else if (c == '&' || c == '|') {
                while (!ops.isEmpty() && precedence(ops.peek()) >= precedence(c)) {
                    applyOp(stack, ops.pop());
                }
                ops.push(c);
            }
        }
        while (!ops.isEmpty()) {
            applyOp(stack, ops.pop());
        }

        int[] result = stack.pop();
        System.out.println(result[0] + " " + result[1]);
    }

    static int precedence(char op) {
        if (op == '&') return 2;
        if (op == '|') return 1;
        return 0;
    }

    static void applyOp(Deque<int[]> stack, char op) {
        int[] right = stack.pop();
        int[] left = stack.pop();
        int[] res = new int[2];

        if (op == '&') {
            // To get 0: 
            // - left 0 costs left[0], right can be anything
            // - left=1 & right=0 costs left[1] + right[0]
            res[0] = Math.min(left[0], left[1] + right[0]);
            // To get 1: both must be 1
            res[1] = left[1] + right[1];
        } else { // '|'
            // To get 0: both must be 0
            res[0] = left[0] + right[0];
            // To get 1:
            // - left=1 costs left[1], right anything
            // - left=0 & right=1 costs left[0] + right[1]
            res[1] = Math.min(left[1], left[0] + right[1]);
        }
        stack.push(res);
    }
}

