public class Main {
    static String s;
    static int pos;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        s = sc.nextLine().trim();
        pos = 0;
        long[] result = parseOrExpr();
        System.out.println(result[0] + " " + result[1]);
    }

    // returns [cost_to_get_0, cost_to_get_1]
    static long[] parseOrExpr() {
        long[] left = parseAndExpr();
        while (pos < s.length() && s.charAt(pos) == '|') {
            pos++; // consume '|'
            long[] right = parseAndExpr();
            long[] combined = new long[2];
            // OR: to get 0: both 0
            combined[0] = left[0] + right[0];
            // OR: to get 1: left=1 (right free) OR left=0,right=1
            combined[1] = Math.min(left[1], left[0] + right[1]);
            left = combined;
        }
        return left;
    }

    static long[] parseAndExpr() {
        long[] left = parseTerm();
        while (pos < s.length() && s.charAt(pos) == '&') {
            pos++;
            long[] right = parseTerm();
            long[] combined = new long[2];
            // AND: to get 1: both 1
            combined[1] = left[1] + right[1];
            // AND: to get 0: left=0 (right free) OR left=1,right=0
            combined[0] = Math.min(left[0], left[1] + right[0]);
            left = combined;
        }
        return left;
    }

    static long[] parseTerm() {
        if (s.charAt(pos) == '(') {
            pos++;
            long[] result = parseOrExpr();
            pos++; // ')'
            return result;
        } else { // '?'
            pos++;
            return new long[]{1, 1};
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }

    static class Node {
        long zero, one; // minimum cost to force this subexpression to 0 / 1
        Node(long z, long o) {
            zero = z;
            one = o;
        }
    }

    static String s;
    static int pos;

    static Node parseOr() {
        Node cur = parseAnd();
        while (pos < s.length() && s.charAt(pos) == '|') {
            pos++;
            Node right = parseAnd();
            cur = combineOr(cur, right);
        }
        return cur;
    }

    static Node parseAnd() {
        Node cur = parseTerm();
        while (pos < s.length() && s.charAt(pos) == '&') {
            pos++;
            Node right = parseTerm();
            cur = combineAnd(cur, right);
        }
        return cur;
    }

    static Node parseTerm() {
        char c = s.charAt(pos);
        if (c == '?') {
            pos++;
            return new Node(1, 1);
        } else { // '('
            pos++;
            Node inside = parseOr();
            pos++; // ')'
            return inside;
        }
    }

    static Node combineAnd(Node a, Node b) {
        long zero = Math.min(
                Math.min(a.zero + b.zero, a.zero + b.one),
                a.one + b.zero
        );
        long one = a.one + b.one;
        return new Node(zero, one);
    }

    static Node combineOr(Node a, Node b) {
        long zero = a.zero + b.zero;
        long one = Math.min(
                Math.min(a.one + b.zero, a.zero + b.one),
                a.one + b.one
        );
        return new Node(zero, one);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        s = fs.next();
        pos = 0;
        Node ans = parseOr();
        System.out.println(ans.zero + " " + ans.one);
    }
}
